const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, BorderStyle, WidthType, ShadingType, ImageRun,
        PageBreak, Header, Footer, TabStopType, TabStopPosition,
        LevelFormat, UnderlineType } = require('docx');

// MCR Logos and QBR cover image embedded as base64
const LOGO_SEASALT  = '';
const LOGO_CARBON   = '';
const QBR_IMAGE    = '';
const LOGO_MASTER   = '';

function b64ToBuffer(b64) {
  return Buffer.from(b64, 'base64');
}

exports.handler = async function(event) {
  if (event.httpMethod === 'OPTIONS') {
    return { statusCode: 200, headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    }, body: '' };
  }
  if (event.httpMethod !== 'POST') return { statusCode: 405, body: 'Method Not Allowed' };

  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { statusCode: 500, headers: cors, body: JSON.stringify({ error: { message: 'API key not configured.' } }) };

  let body;
  try { body = JSON.parse(event.body); }
  catch(e) { return { statusCode: 400, headers: cors, body: JSON.stringify({ error: { message: 'Invalid request' } }) }; }

  try {
    const aiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 4000, system: body.system, messages: body.messages }),
    });
    if (!aiRes.ok) {
      const err = await aiRes.json().catch(() => ({ error: { message: aiRes.statusText } }));
      return { statusCode: aiRes.status, headers: cors, body: JSON.stringify(err) };
    }
    const aiData = await aiRes.json();
    const txt = aiData.content.map(c => c.text || '').join('');
    const clean = txt.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
    const ai = JSON.parse(clean);

    const d = body.formData;
    const docxBuf = await buildDocx(d, ai);
    const fname = (d.orgName || 'QBR').replace(/[^a-zA-Z0-9 _-]/g,'') + '_QBR_' + (d.meetingDate || new Date().toISOString().split('T')[0]) + '.docx';

    return { statusCode: 200, headers: cors, body: JSON.stringify({ docx: docxBuf.toString('base64'), filename: fname }) };
  } catch(err) {
    return { statusCode: 500, headers: cors, body: JSON.stringify({ error: { message: err.message } }) };
  }
};

async function buildDocx(d, ai) {
  // ── COLOURS ──────────────────────────────────────────
  const G='1C4E4F', MT='D7E7E1', CE='B6D2AD', CA='101418', GUN='142828', SS='F6FAF9', CAM='79A682';
  const bd = { style: BorderStyle.SINGLE, size: 1, color: CE };
  const bds = { top: bd, bottom: bd, left: bd, right: bd };
  const noBorder = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
  const noBds = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

  // ── HELPERS ───────────────────────────────────────────
  function fDate(dt) {
    if (!dt) return '—';
    const parts = dt.split('-');
    if (parts.length < 3) return dt;
    const ms = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    return parseInt(parts[2]) + ' ' + ms[parseInt(parts[1])-1] + ' ' + parts[0];
  }

  function h1(icon, text) {
    return new Paragraph({
      children: [new TextRun({ text: icon + '  ' + text, font: 'Calibri', size: 28, bold: true, color: G })],
      spacing: { before: 300, after: 120 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: CE, space: 4 } }
    });
  }
  function h2(text) {
    return new Paragraph({ children: [new TextRun({ text, font: 'Calibri', size: 24, bold: true, color: GUN })], spacing: { before: 160, after: 60 } });
  }
  function para(text, col, size) {
    return new Paragraph({ children: [new TextRun({ text: String(text||''), font: 'Calibri', size: size||22, color: col||CA })], spacing: { after: 80 } });
  }
  function bullet(text) {
    return new Paragraph({
      numbering: { reference: 'bullets', level: 0 },
      children: [new TextRun({ text: String(text||''), font: 'Calibri', size: 22, color: CA })],
      spacing: { after: 60 }
    });
  }
  function sp(n) { return new Paragraph({ children: [new TextRun({ text: '', size: 20 })], spacing: { after: n||80 } }); }
  function hCell(text, w) {
    return new TableCell({ borders: bds, width: { size: w, type: WidthType.DXA },
      shading: { fill: MT, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({ children: [new TextRun({ text: String(text||''), font: 'Calibri', size: 18, bold: true, color: GUN })] })] });
  }
  function dCell(text, w, fill) {
    return new TableCell({ borders: bds, width: { size: w, type: WidthType.DXA },
      shading: fill ? { fill, type: ShadingType.CLEAR } : undefined,
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({ children: [new TextRun({ text: String(text||''), font: 'Calibri', size: 20, color: CA })] })] });
  }
  function trow(cells) { return new TableRow({ children: cells }); }
  function tbl(total, cols, rows) { return new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: cols, rows }); }

  function imgFromB64(b64, w, h) {
    try {
      const buf = Buffer.from(b64.split(',')[1] || b64, 'base64');
      return new ImageRun({ type: 'jpg', data: buf, transformation: { width: w, height: h }, altText: { title: 'Dashboard', description: '', name: 'img' } });
    } catch(e) { return null; }
  }

  function linkPara(label, url) {
    return new Paragraph({
      children: [
        new TextRun({ text: label + ': ', font: 'Calibri', size: 20, bold: true, color: G }),
        new TextRun({ text: url, font: 'Calibri', size: 20, color: '0563C1', underline: { type: UnderlineType.SINGLE } }),
      ],
      spacing: { after: 60 }
    });
  }

  // ── COVER PAGE ────────────────────────────────────────
  const coverKids = [];

  // QBR cover image - transparent background on white page
  const qbrImgBuf = b64ToBuffer(QBR_IMAGE);
  const qbrImg = new ImageRun({ type: 'png', data: qbrImgBuf, transformation: { width: 220, height: 275 }, altText: { title: 'QBR', description: '', name: 'QBRImage' } });
  coverKids.push(new Paragraph({ children: [qbrImg], alignment: AlignmentType.CENTER, spacing: { before: 300, after: 200 } }));

  // QBR Title
  coverKids.push(new Paragraph({
    children: [new TextRun({ text: 'Quarterly Business Review', font: 'Calibri', size: 56, bold: true, color: G })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 400, after: 120 }
  }));

  // Client name large
  coverKids.push(new Paragraph({
    children: [new TextRun({ text: d.orgName || '', font: 'Calibri', size: 72, bold: true, color: GUN })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 }
  }));

  // Divider line
  coverKids.push(new Paragraph({
    children: [new TextRun({ text: '', size: 4 })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: CE, space: 1 } },
    spacing: { after: 300 }
  }));

  // Cover details table
  coverKids.push(tbl(9360, [2200, 7160], [
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'Date', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: fDate(d.meetingDate), font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'Time', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: d.meetingTime || '—', font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'Location', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: d.location || '—', font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'Client Attendees', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: (d.clientAtts||[]).join(', ') || '—', font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'MCR Attendees', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: (d.mcrAtts||[]).join(', ') || '—', font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
    trow([
      new TableCell({ borders: noBds, width: { size: 2200, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: 'Apologies', font: 'Calibri', size: 22, bold: true, color: G })] })] }),
      new TableCell({ borders: noBds, width: { size: 7160, type: WidthType.DXA }, margins: { top: 80, bottom: 80, left: 0, right: 0 },
        children: [new Paragraph({ children: [new TextRun({ text: (d.apologies||[]).join(', ') || 'None', font: 'Calibri', size: 22, color: CA })] })] }),
    ]),
  ]));

  // MCR Master logo below details
  const masterLogoBuf = b64ToBuffer(LOGO_MASTER);
  const masterLogoImg = new ImageRun({ type: 'jpg', data: masterLogoBuf, transformation: { width: 220, height: 100 }, altText: { title: 'MCR Systems', description: '', name: 'MCRMasterLogo' } });
  coverKids.push(sp(120));
  coverKids.push(new Paragraph({ children: [masterLogoImg], alignment: AlignmentType.CENTER, spacing: { before: 200, after: 200 } }));

  // Page break after cover
  coverKids.push(new Paragraph({ children: [new PageBreak()] }));

  // ── MAIN CONTENT ──────────────────────────────────────
  const kids = [];

  // Key Updates
  if (ai.keyUpdates && ai.keyUpdates.length) {
    kids.push(h1('📌', 'Key Updates Since Last Meeting'));
    kids.push(tbl(9360, [3000,4000,2360], [trow([hCell('Topic',3000),hCell('Update',4000),hCell('Notes / Actions',2360)])].concat(
      ai.keyUpdates.map(u => trow([dCell(u.topic,3000), dCell(u.update,4000), dCell(u.notes,2360)]))
    )));
    kids.push(sp());
  }

  // Points Raised
  if (ai.pointsRaised && ai.pointsRaised.length) {
    kids.push(h1('📌', 'Points Raised'));
    ai.pointsRaised.forEach(pt => { kids.push(h2(pt.heading)); kids.push(para(pt.narrative)); kids.push(sp(60)); });
    kids.push(sp());
  }

  // Strategic Discussions
  if (ai.strategicDiscussions && ai.strategicDiscussions.length) {
    kids.push(h1('💡', 'Strategic Discussions'));
    ai.strategicDiscussions.forEach(s => kids.push(bullet(s)));
    kids.push(sp());
  }

  // Support Overview
  if (ai.supportPoints && ai.supportPoints.length) {
    kids.push(h1('🛠️', 'Support Overview'));
    ai.supportPoints.forEach(s => kids.push(bullet(s)));
    kids.push(sp(60));
  }

  // Support Dashboard image
  if (d.d1) {
    const img = imgFromB64(d.d1, 610, 300);
    if (img) { kids.push(new Paragraph({ children: [img], alignment: AlignmentType.CENTER })); kids.push(sp()); }
  }

  // KPI Dashboards
  kids.push(h1('📊', 'KPI Dashboards'));
  let hasKpiImg = false;
  if (d.d2) {
    const img = imgFromB64(d.d2, 610, 300);
    if (img) { kids.push(para('Contract KPI Dashboard', G, 22)); kids.push(new Paragraph({ children: [img], alignment: AlignmentType.CENTER })); kids.push(sp(60)); hasKpiImg = true; }
  }
  if (d.d3) {
    const img = imgFromB64(d.d3, 610, 300);
    if (img) { kids.push(para('KPI Performance Dashboard', G, 22)); kids.push(new Paragraph({ children: [img], alignment: AlignmentType.CENTER })); kids.push(sp(60)); hasKpiImg = true; }
  }
  if (!hasKpiImg) { kids.push(para('Dashboard screenshots not attached.', '888888')); }
  kids.push(sp());

  // Survey & KPI Status
  kids.push(h1('📊', 'Survey & KPI Status'));
  kids.push(para('Status: ' + (d.surveyStatus||'—')));
  if (d.surveyNotes) kids.push(para('Notes: ' + d.surveyNotes));
  kids.push(sp());

  // Upcoming Dates
  kids.push(h1('📅', 'Upcoming Dates'));
  const validDates = (d.dates||[]).filter(dt => dt.event || dt.date);
  if (validDates.length) {
    kids.push(tbl(9360, [2200,1900,1400,3860], [trow([hCell('Event',2200),hCell('Date',1900),hCell('Time',1400),hCell('Notes',3860)])].concat(
      validDates.map(dt => trow([dCell(dt.event,2200), dCell(fDate(dt.date),1900), dCell(dt.time,1400), dCell(dt.notes,3860)]))
    )));
  } else { kids.push(para('No upcoming dates recorded.')); }
  kids.push(sp());

  // Outstanding Quotes
  kids.push(h1('💰', 'Outstanding & New Quotes'));
  const vq = (d.quotes||[]).filter(q => q.qn || q.desc);
  if (vq.length) {
    kids.push(tbl(9360, [1800,3760,1300,2500], [trow([hCell('Quote #',1800),hCell('Description',3760),hCell('Value (ex. VAT)',1300),hCell('Status',2500)])].concat(
      vq.map(q => trow([dCell(q.qn,1800), dCell(q.desc,3760), dCell('£'+q.val,1300), dCell(q.status,2500)]))
    )));
  } else { kids.push(para('No outstanding quotes.')); }
  kids.push(sp());

  // Action Items
  if (ai.actionItems && ai.actionItems.length) {
    kids.push(h1('✅', 'Action Items'));
    kids.push(tbl(9360, [3560,2000,1800,2000], [trow([hCell('Task',3560),hCell('Owner(s)',2000),hCell('Deadline',1800),hCell('Status',2000)])].concat(
      ai.actionItems.map(a => trow([dCell(a.task,3560), dCell(a.owner,2000), dCell(fDate(a.deadline),1800), dCell(a.status,2000)]))
    )));
    kids.push(sp());
  }

  // Contract Info
  kids.push(h1('📋', 'Contract Information'));
  kids.push(tbl(9360, [2340,2340,2340,2340], [
    trow([hCell('Annual Renewal',2340),hCell('Contract End',2340),hCell('Windows Expiry',2340),hCell('Till Version',2340)]),
    trow([dCell(d.renewalDate||'—',2340), dCell(d.contractEnd||'—',2340), dCell(d.winExpiry||'—',2340), dCell(d.tillVer||'—',2340)])
  ]));
  kids.push(sp());

  // Additional Notes
  if (d.extraNotes) {
    kids.push(h1('📝', 'Additional Notes'));
    kids.push(para(d.extraNotes));
    kids.push(sp());
  }

  // Useful Links
  kids.push(h1('🔗', 'Useful Links'));
  kids.push(linkPara('SymLive Login', 'https://www.symlive.net/login.aspx'));
  kids.push(linkPara('SymHub Login', 'https://www.symphonyhub.tech/login'));
  kids.push(sp(200));

  // Footer disclaimer
  kids.push(new Paragraph({
    children: [new TextRun({ text: 'All prices quoted are exclusive of VAT at the prevailing rate. Pricing is indicative and based on current costs. Formal quotations will be provided upon request.', font: 'Calibri', size: 16, color: '888888', italics: true })],
    alignment: AlignmentType.CENTER,
    border: { top: { style: BorderStyle.SINGLE, size: 4, color: CE, space: 4 } },
    spacing: { before: 200, after: 80 }
  }));
  kids.push(new Paragraph({
    children: [new TextRun({ text: 'Confidential — MCR Systems © ' + new Date().getFullYear(), font: 'Calibri', size: 16, color: GUN })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }));

  // ── ASSEMBLE DOCUMENT ─────────────────────────────────
  const carbonLogoBuf = b64ToBuffer(LOGO_CARBON);
  const headerLogo = new ImageRun({ type: 'jpg', data: carbonLogoBuf, transformation: { width: 100, height: 46 }, altText: { title: 'MCR Systems', description: '', name: 'MCRLogoHeader' } });

  const doc = new Document({
    numbering: {
      config: [{
        reference: 'bullets',
        levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      }]
    },
    sections: [
      // Cover page section (no header/footer)
      {
        properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1440, right: 1296, bottom: 1440, left: 1296 } } },
        children: coverKids
      },
      // Main content section (with header)
      {
        properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1200, right: 1296, bottom: 1200, left: 1296 } } },
        headers: {
          default: new Header({
            children: [
              new Table({
                width: { size: 9360, type: WidthType.DXA },
                columnWidths: [4680, 4680],
                rows: [trow([
                  new TableCell({ borders: noBds, width: { size: 4680, type: WidthType.DXA },
                    children: [new Paragraph({ children: [new TextRun({ text: 'Quarterly Business Review — ' + (d.orgName||''), font: 'Calibri', size: 18, color: G, bold: true })], alignment: AlignmentType.LEFT })] }),
                  new TableCell({ borders: noBds, width: { size: 4680, type: WidthType.DXA },
                    children: [new Paragraph({ children: [new ImageRun({ type: 'jpg', data: carbonLogoBuf, transformation: { width: 80, height: 37 }, altText: { title: 'MCR', description: '', name: 'h' } })], alignment: AlignmentType.RIGHT })] }),
                ])]
              }),
              new Paragraph({ children: [new TextRun({ text: '', size: 4 })], border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: CE, space: 2 } } })
            ]
          })
        },
        footers: {
          default: new Footer({
            children: [new Paragraph({
              children: [new TextRun({ text: fDate(d.meetingDate) + '  |  MCR Systems  |  Confidential', font: 'Calibri', size: 16, color: '888888' })],
              alignment: AlignmentType.CENTER,
              border: { top: { style: BorderStyle.SINGLE, size: 4, color: CE, space: 2 } }
            })]
          })
        },
        children: kids
      }
    ]
  });

  return await Packer.toBuffer(doc);
}
